{
  "title": "Youth Fitness Programme Impact Report",
  "subtitle": "Measuring physical fitness gains and core strength progression from baseline to endline",
  "panels": [
    {
      "id": "p1",
      "kind": "kpi",
      "title": "Evaluated Children",
      "sql": "SELECT COUNT(DISTINCT b.\"Child ID\") AS total_children FROM \"baseline\" b INNER JOIN \"endline\" e ON b.\"Child ID\" = e.\"Child ID\"",
      "unit": ""
    },
    {
      "id": "p2",
      "kind": "kpi",
      "title": "Avg Sit-Up Increase",
      "sql": "SELECT AVG(e.\"Sit ups\" - b.\"Sit ups\") AS avg_situp_gain FROM \"baseline\" b INNER JOIN \"endline\" e ON b.\"Child ID\" = e.\"Child ID\"",
      "unit": "reps"
    },
    {
      "id": "p3",
      "kind": "kpi",
      "title": "Avg Shuttle Run Improvement",
      "sql": "SELECT AVG(b.\"Shuttle run sec\" - e.\"Shuttle run sec\") AS avg_sec_faster FROM \"baseline\" b INNER JOIN \"endline\" e ON b.\"Child ID\" = e.\"Child ID\"",
      "unit": "s"
    },
    {
      "id": "p4",
      "kind": "bar",
      "title": "Core Strength: Baseline vs Endline Sit-Ups by Age Group",
      "sql": "SELECT CAST(b.\"Age\" AS VARCHAR) AS age_group, AVG(b.\"Sit ups\") AS baseline_situps, AVG(e.\"Sit ups\") AS endline_situps FROM \"baseline\" b INNER JOIN \"endline\" e ON b.\"Child ID\" = e.\"Child ID\" GROUP BY 1 ORDER BY 1",
      "x": "age_group",
      "y": ["baseline_situps", "endline_situps"]
    },
    {
      "id": "p5",
      "kind": "bar",
      "title": "Speed & Agility: Baseline vs Endline Shuttle Run (Seconds)",
      "sql": "SELECT b.\"Gender\" AS gender, AVG(b.\"Shuttle run sec\") AS baseline_shuttle_sec, AVG(e.\"Shuttle run sec\") AS endline_shuttle_sec FROM \"baseline\" b INNER JOIN \"endline\" e ON b.\"Child ID\" = e.\"Child ID\" GROUP BY 1 ORDER BY 1",
      "x": "gender",
      "y": ["baseline_shuttle_sec", "endline_shuttle_sec"]
    },
    {
      "id": "p6",
      "kind": "table",
      "title": "Top Locations by Average Sit-Up Gain",
      "sql": "SELECT b.\"Location\" AS location, COUNT(DISTINCT b.\"Child ID\") AS participants, ROUND(AVG(b.\"Sit ups\"), 1) AS avg_baseline_situps, ROUND(AVG(e.\"Sit ups\"), 1) AS avg_endline_situps, ROUND(AVG(e.\"Sit ups\" - b.\"Sit ups\"), 1) AS avg_gain FROM \"baseline\" b INNER JOIN \"endline\" e ON b.\"Child ID\" = e.\"Child ID\" GROUP BY 1 ORDER BY avg_gain DESC LIMIT 10"
    }
  ],
  "narrative": "A total of {{p1}} children participated in both the baseline and endline assessments across programme locations. The interventions demonstrated tangible gains in both muscular endurance and athletic agility.\n\nOverall, participants increased their core strength performance with an average gain of {{p2}} sit-up repetitions. Speed and agility also showed clear progression, with shuttle run times improving by an average reduction of {{p3}} seconds.\n\nPerformance enhancements were consistent across genders and age categories, underscoring strong training delivery and sustained participant engagement throughout the intervention period."
}
